typedef struct
{
  uint32_t AreaId; /*!< Area identifier field. It can be a value of @ref
                        GTZC_MPCWM_AreaId */
  uint32_t Length; /*!< length of the unprivileged area starting from selected
                        memory base address. It must be aligned on 2kB for Flash
