#ifdef CORE_CM0PLUS
  LL_PWR_WriteReg(EXTSCR,
                  LL_PWR_EXTSCR_C2CSSF
                 );
#else
  LL_PWR_WriteReg(EXTSCR,
                  LL_PWR_EXTSCR_C1CSSF
                 );
#endif /* CORE_CM0PLUS */

  return SUCCESS;
}

